with base as (select id, customer_id, device, country, concat_ws('-', device, country) as device_country_key, coalesce(browser, 'OTHER') as browser_filled from sessions where customer_id is not null) select country, count(distinct device) as distinct_devices, count(*) filter (where device = 'desktop') as desktop_rows, sort_array(collect_set(country)) as country_list, sort_array(collect_set(country)) as country_list_2, count(*) as row_count, count(*) as row_count_2 from base group by country order by row_count_2 nulls last
